import{_ as d,a0 as o,w as p,s as r,I as i,x as t,a1 as l,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"理解 Linux 链接（一） | LCTT x X-CMD","titleTemplate":false,"description":"理解 Linux 链接（一） | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解 Linux 链接（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解 Linux 链接（一） | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181018 Understanding Linux Links- Part 1","title":"理解 Linux 链接（一）","tag":"201810","desc":""},"relativePath":"201810/20181018 Understanding Linux Links- Part 1.md","filePath":"[post].md"}'),u={name:"201810/20181018 Understanding Linux Links- Part 1.md"};function g(b,s,k,h,x,f){const e=o("Link");return p(),r("div",null,[s[36]||(s[36]=i("h1",{id:"理解-linux-链接-一",tabindex:"-1"},[t("理解 Linux 链接（一） "),i("a",{class:"header-anchor",href:"#理解-linux-链接-一","aria-label":"Permalink to “理解 Linux 链接（一）”"},"​")],-1)),s[37]||(s[37]=i("blockquote",null,[i("p",null,"链接是可以将文件和目录放在你希望它们放在的位置的另一种方式。")],-1)),s[38]||(s[38]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/linux-link-498708.jpg?itok=DyVEcEsc",alt:""})],-1)),i("p",null,[s[1]||(s[1]=t("除了 ",-1)),s[2]||(s[2]=i("code",null,"cp",-1)),s[3]||(s[3]=t(" 和 ",-1)),s[4]||(s[4]=i("code",null,"mv",-1)),s[5]||(s[5]=t(" 这两个我们在",-1)),l(e,{href:"https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around"},{default:n(()=>[...s[0]||(s[0]=[t("本系列的前一部分",-1)])]),_:1}),s[6]||(s[6]=t("中详细讨论过的，链接是可以将文件和目录放在你希望它们放在的位置的另一种方式。它的优点是可以让你同时在多个位置显示一个文件或目录。",-1))]),s[39]||(s[39]=a(`<p>如前所述，在物理磁盘这个级别上，文件和目录之类的东西并不真正存在。文件系统是为了方便人类使用，将它们虚构出来。但在磁盘级别上，有一个名为<ruby>分区表<rt>partition table</rt></ruby>的东西，它位于每个分区的开头，然后数据分散在磁盘的其余部分。</p><p>虽然有不同类型的分区表，但是在分区开头的那个表包含的数据将映射每个目录和文件的开始和结束位置。分区表的就像一个索引：当从磁盘加载文件时，操作系统会查找表中的条目，分区表会告诉文件在磁盘上的起始位置和结束位置。然后磁盘头移动到起点，读取数据，直到它到达终点，您看：这就是你的文件。</p><h3 id="硬链接" tabindex="-1">硬链接 <a class="header-anchor" href="#硬链接" aria-label="Permalink to “硬链接”">​</a></h3><p>硬链接只是分区表中的一个条目，它指向磁盘上的某个区域，表示该区域<strong>已经被分配给文件</strong>。换句话说，硬链接指向已经被另一个条目索引的数据。让我们看看它是如何工作的。</p><p>打开终端，创建一个实验目录并进入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir test_dir</span></span>
<span class="line"><span>cd test_dir</span></span></code></pre></div>`,6)),i("p",null,[s[8]||(s[8]=t("使用 ",-1)),l(e,{href:"https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around"},{default:n(()=>[...s[7]||(s[7]=[t("touch",-1)])]),_:1}),s[9]||(s[9]=t(" 创建一个文件：",-1))]),s[40]||(s[40]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch test.txt</span></span></code></pre></div><p>为了获得更多的体验（？），在文本编辑器中打开 <code>test.txt</code> 并添加一些单词。</p><p>现在通过执行以下命令来建立硬链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln test.txt hardlink_test.txt</span></span></code></pre></div><p>运行 <code>ls</code>，你会看到你的目录现在包含两个文件，或者看起来如此。正如你之前读到的那样，你真正看到的是完全相同的文件的两个名称： <code>hardlink_test.txt</code> 包含相同的内容，没有填充磁盘中的任何更多空间（可以尝试使用大文件来测试），并与 <code>test.txt</code> 使用相同的 inode：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li *test*</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 hardlink_test.txt</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 test.txt</span></span></code></pre></div><p><code>ls</code> 的 <code>-i</code> 选项显示一个文件的 “inode 数值”。“inode” 是分区表中的信息块，它包含磁盘上文件或目录的位置、上次修改的时间以及其它数据。如果两个文件使用相同的 inode，那么无论它们在目录树中的位置如何，它们在实际上都是相同的文件。</p><h3 id="软链接" tabindex="-1">软链接 <a class="header-anchor" href="#软链接" aria-label="Permalink to “软链接”">​</a></h3><p>软链接，也称为<ruby>符号链接<rt>symlink</rt></ruby>，它与硬链接是不同的：软链接实际上是一个独立的文件，它有自己的 inode 和它自己在磁盘上的小块地方。但它只包含一小段数据，将操作系统指向另一个文件或目录。</p><p>你可以使用 <code>ln</code> 的 <code>-s</code> 选项来创建一个软链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s test.txt softlink_test.txt</span></span></code></pre></div><p>这将在当前目录中创建软链接 <code>softlink_test.txt</code>，它指向 <code>test.txt</code>。</p><p>再次执行 <code>ls -li</code>，你可以看到两种链接的不同之处：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 hardlink_test.txt</span></span>
<span class="line"><span>16515855 lrwxrwxrwx 1 paul paul 8 oct 12 09:50 softlink_test.txt -&gt; test.txt</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 test.txt</span></span></code></pre></div><p><code>hardlink_test.txt</code> 和 <code>test.txt</code> 包含一些文本并且<em>字面上</em>占据相同的空间。它们使用相同的 inode 数值。与此同时，<code>softlink_test.txt</code> 占用少得多，并且具有不同的 inode 数值，将其标记为完全不同的文件。使用 <code>ls</code> 的 <code>-l</code> 选项还会显示软链接指向的文件或目录。</p><h3 id="为什么要用链接" tabindex="-1">为什么要用链接？ <a class="header-anchor" href="#为什么要用链接" aria-label="Permalink to “为什么要用链接？”">​</a></h3>`,16)),i("p",null,[s[11]||(s[11]=t("它们适用于",-1)),s[12]||(s[12]=i("strong",null,"带有自己环境的应用程序",-1)),s[13]||(s[13]=t("。你的 Linux 发行版通常不会附带你需要应用程序的最新版本。以优秀的 ",-1)),l(e,{href:"https://www.blender.org/"},{default:n(()=>[...s[10]||(s[10]=[t("Blender 3D",-1)])]),_:1}),s[14]||(s[14]=t(" 设计软件为例，Blender 允许你创建 3D 静态图像以及动画电影，人人都想在自己的机器上拥有它。问题是，当前版本的 Blender 至少比任何发行版中的自带的高一个版本。",-1))]),i("p",null,[s[16]||(s[16]=t("幸运的是，",-1)),l(e,{href:"https://www.blender.org/download/"},{default:n(()=>[...s[15]||(s[15]=[t("Blender 提供可以开箱即用的下载",-1)])]),_:1}),s[17]||(s[17]=t("。除了程序本身之外，这些软件包还包含了 Blender 需要运行的复杂的库和依赖框架。所有这些数据和块都在它们自己的目录层次中。",-1))]),s[41]||(s[41]=a('<p>每次你想运行 Blender，你都可以 <code>cd</code> 到你下载它的文件夹并运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./blender</span></span></code></pre></div><p>但这很不方便。如果你可以从文件系统的任何地方，比如桌面命令启动器中运行 <code>blender</code> 命令会更好。</p><p>这样做的方法是将 <code>blender</code> 可执行文件链接到 <code>bin/</code> 目录。在许多系统上，你可以通过将其链接到文件系统中的任何位置来使 <code>blender</code> 命令可用，就像这样。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /path/to/blender_directory/blender /home/&lt;username&gt;/bin</span></span></code></pre></div><p>你需要链接的另一个情况是<strong>软件需要过时的库</strong>。如果你用 <code>ls -l</code> 列出你的 <code>/usr/lib</code> 目录，你会看到许多软链接文件一闪而过。仔细看看，你会看到软链接通常与它们链接到的原始文件具有相似的名称。你可能会看到 <code>libblah</code> 链接到 <code>libblah.so.2</code>，你甚至可能会注意到 <code>libblah.so.2</code> 相应链接到原始文件 <code>libblah.so.2.1.0</code>。</p><p>这是因为应用程序通常需要安装比已安装版本更老的库。问题是，即使新版本仍然与旧版本（通常是）兼容，如果程序找不到它正在寻找的版本，程序将会出现问题。为了解决这个问题，发行版通常会创建链接，以便挑剔的应用程序<strong>相信</strong>它找到了旧版本，实际上它只找到了一个链接并最终使用了更新的库版本。</p><p>有些是和<strong>你自己从源代码编译的程序</strong>相关。你自己编译的程序通常最终安装在 <code>/usr/local</code> 下，程序本身最终在 <code>/usr/local/bin</code> 中，它在 <code>/usr/local/bin</code> 目录中查找它需要的库。但假设你的新程序需要 <code>libblah</code>，但 <code>libblah</code> 在 <code>/usr/lib</code> 中，这就是所有其它程序都会寻找到它的地方。你可以通过执行以下操作将其链接到 <code>/usr/local/lib</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /usr/lib/libblah /usr/local/lib</span></span></code></pre></div><p>或者如果你愿意，可以 <code>cd</code> 到 <code>/usr/local/lib</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /usr/local/lib</span></span></code></pre></div><p>然后使用链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s ../lib/libblah</span></span></code></pre></div><p>还有几十个案例证明软链接是有用的，当你使用 Linux 更熟练时，你肯定会发现它们，但这些是最常见的。下一次，我们将看一些你需要注意的链接怪异。</p>',14)),i("p",null,[s[19]||(s[19]=t("通过 Linux 基金会和 edX 的免费 ",-1)),l(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:n(()=>[...s[18]||(s[18]=[t("“Linux 简介”",-1)])]),_:1}),s[20]||(s[20]=t("课程了解有关 Linux 的更多信息。",-1))]),s[42]||(s[42]=i("hr",null,null,-1)),i("p",null,[s[22]||(s[22]=t("via: ",-1)),l(e,{href:"https://www.linux.com/blog/intro-to-linux/2018/10/linux-links-part-1"},{default:n(()=>[...s[21]||(s[21]=[t("https://www.linux.com/blog/intro-to-linux/2018/10/linux-links-part-1",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/bro66"},{default:n(()=>[...s[23]||(s[23]=[t("Paul Brown",-1)])]),_:1}),s[28]||(s[28]=t(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[24]||(s[24]=[t("lujun9972",-1)])]),_:1}),s[29]||(s[29]=t(" 译者：",-1)),l(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[25]||(s[25]=[t("MjSeven",-1)])]),_:1}),s[30]||(s[30]=t(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[26]||(s[26]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[33]||(s[33]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[31]||(s[31]=[t("LCTT",-1)])]),_:1}),s[34]||(s[34]=t(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...s[32]||(s[32]=[t("Linux中国",-1)])]),_:1}),s[35]||(s[35]=t(" 荣誉推出",-1))])])}const C=d(u,[["render",g]]);export{y as __pageData,C as default};
